CSS:
.demo {
  position: relative;
  padding-top: 20px;
  padding-bottom: 20px;
  border-top: 2px solid black;
  border-bottom: 2px solid black;
}
.demo::before,
.demo::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background-color: black;
}
.demo::before {
  top: 0;
}
.demo::after {
  bottom: 0;
}
